const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const authHeader = headers.authorization || '';

// Lấy và làm sạch dữ liệu ngày tháng
const rawDate = (body.leaveDate || body.leave_date || '').trim();
const rawEndDate = (body.end_date || body.endDate || '').trim();

const fmt = (d) => {
  if (!d) return '';
  const pd = new Date(d);
  if (isNaN(pd)) return d;
  return pd.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

// Logic lấy ngày quay lại thực tế (mặc định là ngày hôm nay nếu trống)
const actualReturn = body.actualReturnDate || new Date().toISOString().split('T')[0];

return [{ json: {
  token: authHeader.replace('Bearer ', ''),
  leaveId: body.leaveId || body._id || '',
  actualReturnDate: actualReturn,
  actualReturnDateDisplay: fmt(actualReturn), // Thêm bản hiển thị đẹp cho email
  reason: body.reason || '',
  employeeName: body.employeeName || body.employee_name || '',
  employeeEmail: body.employeeEmail || body.employee_email || '',
  leaveDate: rawDate,
  leaveDateDisplay: fmt(rawDate),
  end_date: rawEndDate,
  endDateDisplay: fmt(rawEndDate),
  leaveDays: parseInt(body.leaveDays || body.leave_days || 0),
  department: body.department || '',
  managerEmail: body.managerEmail || '',
  hrEmail: body.hrEmail || '',
  refundDays: parseInt(body.refundDays || 0),
  // QUAN TRỌNG: Gán cứng URL để tránh lỗi access denied
  frontendUrl: 'https://approvehub.internalautomation.io.vn' 
} }];

const input = $('Parse Input').first().json;

// Backend already updated DB. wf8 only sends notification emails.
// Determine if HR should be notified (leave was >3 days, approved by HR)
const needsHrNotification = input.hrEmail && input.hrEmail !== '';

return [{ json: {
  ...input,
  needsHrNotification,
  // Build HR approval link if applicable
  hrApprovalLink: needsHrNotification
    ? `${input.frontendUrl}/approval-page.html?token=${encodeURIComponent(input.hrApprovalToken || '')}&hr=true`
    : ''
} }];

// 1. Lấy dữ liệu từ node đầu vào
const item = $input.first().json;

// 2. Truy cập node 'Parse Input' để lấy ngày về thực tế
const parseInput = $('Parse Input').first().json;
const actualReturnDate = parseInput.actualReturnDateDisplay || parseInput.actualReturnDate || '';

// 3. Gán các biến chính
const to = item.employeeEmail;
const subject = `Xác nhận hoàn trả ngày phép`;

// 4. Nội dung HTML với tiếng Việt có dấu và căn chỉnh chi tiết
