    <div style="text-align:center; margin:16px 0;"><span class="badge">Đã hoàn trả ngày phép</span></div>

    <table class="details-table">
      <tr><td>Đơn gốc</td><td>${item.leaveDateDisplay} (${item.leaveDays} ngày)</td></tr>
